class Solution:
    def getMinimumDifference(self,root):
        stack=[];node=root;previous=None;answer=inf
        while node or stack:
            while node:stack.append(node);node=node.left
            node=stack.pop()
            if previous is not None:answer=min(answer,node.val-previous)
            previous=node.val;node=node.right
        return answer
